-- Paket ABT "abt-alamat-putusan-28okt" (28 Okt 2026): keterangan arah di dalam KURUNG pada alamat pihak dibuang di PUTUSAN (relaas tetap utuh). 6 variabel diubah (7047, 7048, 8700, 8890, 9349, 9350), 2 fungsi paket 27 Okt diganti, 3 fungsi baru (AP).
-- Prasyarat: paket pihak-urut-ecourt-27okt dan pihak-urut-sisa-28okt sudah terpasang.
-- PERIKSA: tiap variabel persis isi paket; fungsi benar; relaas (7108 7109 9230 9231 9292 9293), alamat langsung blangko (3517 3518 3519 10126) dan eksekusi (3943 3944) tidak tersentuh; baris terakhir "SEMUA COCOK".
SELECT 'var 7047 diubah' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='c8fdb0dade2c0d8c7549caeabca6c08b')) AS cocok;
SELECT 'var 7048 diubah' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='634fce56fc630914fe9446a079c9fa3a')) AS cocok;
SELECT 'var 8700 diubah' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=8700 AND MD5(nama)='cc04924b6d60cd2fe9d0082b9fba493a' AND data_type='data_sql' AND MD5(sql_query)='35fd01b30d22e558cba808e9b293010e')) AS cocok;
SELECT 'var 8890 diubah' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=8890 AND MD5(nama)='af7b94e4c0ef1b79bee1c4bba11bbe8a' AND data_type='data_sql' AND MD5(sql_query)='68d55add7505d14216829b56a0082b7d')) AS cocok;
SELECT 'var 9349 diubah' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=9349 AND MD5(nama)='a15f9d0715b5eae1e50b009c8b557575' AND data_type='data_sql' AND MD5(sql_query)='2d5114c2a87e34daef54c70d75028661')) AS cocok;
SELECT 'var 9350 diubah' AS butir, (SELECT COUNT(*) FROM abt_variabel WHERE (no_var=9350 AND MD5(nama)='40caa4ef1d8b274b9a851f0c6db9ece6' AND data_type='data_sql' AND MD5(sql_query)='212cd5dd2889ef88b2c67e3aeb01f366')) AS cocok;
SELECT 'fungsi AP ada' AS butir, IF((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_alamat_arah' AND MD5(routine_definition)='879b99851e6ee214706c4e5b8271a85c') OR (routine_name='isian_rtf_alamat_buang_arah' AND MD5(routine_definition)='eb549e67f9ddd4d866514c2e82ff120c') OR (routine_name='isian_rtf_alamat_putusan' AND MD5(routine_definition)='c6e37f152a9ea908a747fc59c9209034'))) = 3, 1, 0) AS cocok;
SELECT 'fungsi identitas dan utama baru' AS butir, IF((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='4c758ce53cd541a39a32cf3cb0ba9898') OR (routine_name='isian_rtf_pihak_utama' AND MD5(routine_definition)='ecda2f98c76145e78f4b9b76ef1ceb80'))) = 2, 1, 0) AS cocok;
SELECT 'fungsi jalan' AS butir, IF(isian_rtf_alamat_arah('GAIB') = 0 AND isian_rtf_alamat_arah('rumah sesudah Jembatan / Kios X') = 1 AND isian_rtf_alamat_arah('RT/RW 01/02') = 0 AND isian_rtf_alamat_buang_arah('Jalan Poros Palu-Bangga (rumah sesudah Jembatan / Kios X), Desa Poi') = 'Jalan Poros Palu-Bangga, Desa Poi' AND isian_rtf_alamat_buang_arah('Jalan A (samping SD) , Desa B') = 'Jalan A, Desa B' AND isian_rtf_alamat_buang_arah('Desa C (GAIB), Kec D') = 'Desa C (GAIB), Kec D' AND isian_rtf_alamat_buang_arah('Desa C, Kec D') = 'Desa C, Kec D' AND isian_rtf_alamat_buang_arah(NULL) IS NULL AND isian_rtf_alamat_putusan('Desa Poi (rumah depan Masjid), Kecamatan Dolo Selatan') = isian_rtf_alamat('Desa Poi, Kecamatan Dolo Selatan'), 1, 0) AS cocok;
SELECT 'relaas dan eksekusi tak tersentuh' AS butir, IF((SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (3517,3518,3519,3943,3944,7108,7109,9230,9231,9292,9293,10126) AND sql_query LIKE '%aps_badilag.isian_rtf_alamat(%' AND sql_query NOT LIKE '%isian_rtf_alamat_putusan%') = 12 AND (SELECT COUNT(*) FROM abt_variabel WHERE sql_query LIKE '%isian_rtf_alamat_putusan%') = 6, 1, 0) AS cocok;
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE ((no_var=7047 AND MD5(nama)='64ef74b8b5dfba66d3be3b10a7c9692e' AND data_type='data_sql' AND MD5(sql_query)='c8fdb0dade2c0d8c7549caeabca6c08b') OR (no_var=7048 AND MD5(nama)='0d46332b5be50992e27dfcebf6ec1de4' AND data_type='data_sql' AND MD5(sql_query)='634fce56fc630914fe9446a079c9fa3a') OR (no_var=8700 AND MD5(nama)='cc04924b6d60cd2fe9d0082b9fba493a' AND data_type='data_sql' AND MD5(sql_query)='35fd01b30d22e558cba808e9b293010e') OR (no_var=8890 AND MD5(nama)='af7b94e4c0ef1b79bee1c4bba11bbe8a' AND data_type='data_sql' AND MD5(sql_query)='68d55add7505d14216829b56a0082b7d') OR (no_var=9349 AND MD5(nama)='a15f9d0715b5eae1e50b009c8b557575' AND data_type='data_sql' AND MD5(sql_query)='2d5114c2a87e34daef54c70d75028661') OR (no_var=9350 AND MD5(nama)='40caa4ef1d8b274b9a851f0c6db9ece6' AND data_type='data_sql' AND MD5(sql_query)='212cd5dd2889ef88b2c67e3aeb01f366'))) = 6 AND (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_alamat_arah' AND MD5(routine_definition)='879b99851e6ee214706c4e5b8271a85c') OR (routine_name='isian_rtf_alamat_buang_arah' AND MD5(routine_definition)='eb549e67f9ddd4d866514c2e82ff120c') OR (routine_name='isian_rtf_alamat_putusan' AND MD5(routine_definition)='c6e37f152a9ea908a747fc59c9209034'))) = 3 AND (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND ((routine_name='isian_rtf_pihak_identitas' AND MD5(routine_definition)='4c758ce53cd541a39a32cf3cb0ba9898') OR (routine_name='isian_rtf_pihak_utama' AND MD5(routine_definition)='ecda2f98c76145e78f4b9b76ef1ceb80'))) = 2 AND isian_rtf_alamat_arah('GAIB') = 0 AND isian_rtf_alamat_arah('rumah sesudah Jembatan / Kios X') = 1 AND isian_rtf_alamat_arah('RT/RW 01/02') = 0 AND isian_rtf_alamat_buang_arah('Jalan Poros Palu-Bangga (rumah sesudah Jembatan / Kios X), Desa Poi') = 'Jalan Poros Palu-Bangga, Desa Poi' AND isian_rtf_alamat_buang_arah('Jalan A (samping SD) , Desa B') = 'Jalan A, Desa B' AND isian_rtf_alamat_buang_arah('Desa C (GAIB), Kec D') = 'Desa C (GAIB), Kec D' AND isian_rtf_alamat_buang_arah('Desa C, Kec D') = 'Desa C, Kec D' AND isian_rtf_alamat_buang_arah(NULL) IS NULL AND isian_rtf_alamat_putusan('Desa Poi (rumah depan Masjid), Kecamatan Dolo Selatan') = isian_rtf_alamat('Desa Poi, Kecamatan Dolo Selatan'), 'SEMUA COCOK', 'TIDAK COCOK') AS hasil;
